package com.akviso.threatintel;
import android.app.Activity;import android.os.Bundle;import android.webkit.*;import android.content.*;import java.io.*;import java.net.*;
public class MainActivity extends Activity{
 static final String RAW="https://raw.githubusercontent.com/hslatman/awesome-threat-intelligence/main/README.md";
 WebView w;
 public void onCreate(Bundle b){super.onCreate(b);w=new WebView(this);w.setWebViewClient(new WebViewClient());w.getSettings().setJavaScriptEnabled(true);w.getSettings().setDomStorageEnabled(true);w.addJavascriptInterface(new Bridge(this),"threatIntel");setContentView(w);syncAndLoad();}
 void syncAndLoad(){new Thread(()->{try{HttpURLConnection c=(HttpURLConnection)new URL(RAW).openConnection();c.setRequestProperty("User-Agent","ThreatIntel-Portal");c.setConnectTimeout(10000);c.setReadTimeout(15000);if(c.getResponseCode()==200){BufferedReader r=new BufferedReader(new InputStreamReader(c.getInputStream()));StringBuilder s=new StringBuilder();String x;while((x=r.readLine())!=null)s.append(x).append("\n");if(s.length()>1000)openFileOutput("database.md",MODE_PRIVATE).write(s.toString().getBytes("UTF-8"));r.close();}}catch(Exception ignored){}runOnUiThread(()->w.loadUrl("file:///android_asset/index.html"));}).start();}
 public static class Bridge{Context c;Bridge(Context c){this.c=c;}@JavascriptInterface public String getDatabase(){try{File f=new File(c.getFilesDir(),"database.md");if(f.exists())return read(f);}catch(Exception ignored){}try{InputStream i=c.getAssets().open("README.md");ByteArrayOutputStream o=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=i.read(b))!=-1)o.write(b,0,n);i.close();return o.toString("UTF-8");}catch(Exception e){return "";}}static String read(File f)throws Exception{BufferedReader r=new BufferedReader(new InputStreamReader(new FileInputStream(f),"UTF-8"));StringBuilder s=new StringBuilder();String x;while((x=r.readLine())!=null)s.append(x).append("\n");r.close();return s.toString();}}
}